// island-feedback.js — deterministic design feedback for the reclaimed island.
//
// 1. placementComment()  — a short systems-thinking comment after each building
//    placement, so the player feels the city "reacts" to their design choices.
// 2. computeDesignScore() — the after-simulation island report (score + notes).
// 3. DESIGN_CODE_QUESTIONS — the main city's advice questions for future
//    islands. Content generated by Qwen Max (same voice as the department
//    briefings in the HK hub); copied here so the capstone stays self-contained.
//
// Deterministic on purpose: no AI model needed, feedback always fires.

import { BLD, SYSTEMS, ok } from './city-logic.js';

function manhattan(a, b) {
  return Math.abs(a.row - b.row) + Math.abs(a.col - b.col);
}

function adjacentRoad(game, r, c) {
  const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  for (const [dr, dc] of dirs) {
    const rr = r + dr, cc = c + dc;
    if (!ok(rr, cc)) continue;
    const b = game.bldAt(rr, cc);
    if (b && b.type === 'road') return true;
  }
  return false;
}

// Nearest placed building matching one of `types`; returns { b, d } or { b:null, d:Infinity }.
function nearestOf(game, r, c, types) {
  let best = null, bestD = Infinity;
  for (const b of game.state.buildings) {
    if (!types.includes(b.type)) continue;
    const d = manhattan({ row: r, col: c }, b);
    if (d < bestD) { bestD = d; best = b; }
  }
  return { b: best, d: bestD };
}

const HEALTHY = ['hosp', 'clinic', 'school', 'green'];
const WASTE = ['recycle', 'collect'];
const POWER_SRC = ['solar', 'wind'];

/**
 * Short deterministic comment after placing a building. Returns a string or null
 * (null = neutral placement, no comment). Teaches systems thinking.
 */
export function placementComment(game, type, r, c) {
  const def = BLD[type];
  if (!def) return null;
  const name = def.l;

  // 1. Road access — every functional building should sit beside a road.
  if (type !== 'road' && !adjacentRoad(game, r, c)) {
    return `⚠️ ${name} has no road beside it — the AI routing system can't reach it. Put a road next to it so services can connect.`;
  }

  // 2. Power: renewable sources vs. data centers (the big consumers).
  if (type === 'solar' || type === 'wind') {
    const dc = nearestOf(game, r, c, ['data']);
    if (dc.b && dc.d > 6) {
      return `☀️ ${name} placed — but it's ${dc.d} tiles from the Data Center, so some energy is lost in transit. Nearby consumers are more efficient.`;
    }
    return `☀️ ${name} placed. It can feed power straight into the grid.`;
  }
  if (type === 'data') {
    const p = nearestOf(game, r, c, POWER_SRC);
    if (p.b && p.d <= 4) return `🗄️ Data Center near ${BLD[p.b.type].l} — short power lines, efficient for the AI!`;
    return `🗄️ Data Center placed. Consider putting it near a solar farm or wind turbine to keep it powered.`;
  }

  // 3. Waste: keep recycling / collection away from homes, hospitals, schools.
  if (WASTE.includes(type)) {
    const h = nearestOf(game, r, c, HEALTHY);
    if (h.b && h.d <= 3) {
      return `♻️ ${name} placed next to ${BLD[h.b.type].l} — not ideal for clean air. Waste sites work better away from homes and hospitals.`;
    }
    return `♻️ ${name} placed. A good spot for the city's waste AI.`;
  }
  if (HEALTHY.includes(type)) {
    const w = nearestOf(game, r, c, WASTE);
    if (w.b && w.d <= 3) {
      return `🏥 ${name} placed next to ${BLD[w.b.type].l} — waste processing nearby isn't great for health. Consider separating them.`;
    }
  }

  // 4. Emergency: near hospitals = fast response.
  if (type === 'emerg') {
    const h = nearestOf(game, r, c, ['hosp', 'clinic']);
    if (h.b && h.d <= 4) return `🚨 Emergency station near ${BLD[h.b.type].l} — fast response for the whole district!`;
    return `🚨 Emergency station placed. Near a hospital or clinic it would respond even faster.`;
  }

  return null;   // neutral placement
}

/**
 * After-simulation island report: a 0-100 design score + deterministic notes.
 */
export function computeDesignScore(game) {
  const bs = game.state.buildings;
  const nonRoad = bs.filter(b => b.type !== 'road');
  const notes = [];
  let score = 40;   // base

  // Road connectivity
  const connected = nonRoad.filter(b => adjacentRoad(game, b.row, b.col)).length;
  const connPct = nonRoad.length ? connected / nonRoad.length : 0;
  score += Math.round(connPct * 30);
  if (connPct === 1) notes.push('✅ Every building sits beside a road — the AI routing works everywhere.');
  else if (connPct >= 0.6) notes.push('👍 Most buildings have road access — good connectivity.');
  else notes.push('⚠️ Several buildings have no road beside them — the AI can\'t route services to them.');

  // Power balance
  let energyIn = 0, energyOut = 0;
  for (const b of bs) {
    if (POWER_SRC.includes(b.type)) energyIn += 5;
    if (b.type === 'data') energyOut += 8;
  }
  if (energyOut > 0 && energyIn >= energyOut) { score += 15; notes.push('✅ Power supply covers the data centers — the grid is stable.'); }
  else if (energyOut > 0) { score += 5; notes.push('⚠️ Data centers need more power than the solar/wind farms produce.'); }
  else { score += 8; notes.push('ℹ️ No data centers yet — power demand is low.'); }

  // Waste isolation
  const waste = bs.filter(b => WASTE.includes(b.type));
  const health = bs.filter(b => HEALTHY.includes(b.type));
  let wasteMin = Infinity;
  for (const w of waste) for (const h of health) wasteMin = Math.min(wasteMin, manhattan(w, h));
  if (waste.length && health.length) {
    if (wasteMin > 4) { score += 10; notes.push('✅ Waste sites are well away from homes and hospitals.'); }
    else if (wasteMin > 2) { score += 5; notes.push('👍 Waste sites are reasonably separated from homes.'); }
    else { notes.push('⚠️ Waste processing sits right next to homes or hospitals — not ideal for clean air.'); }
  }

  // System coverage
  const covered = SYSTEMS.filter(s => game.state.req.systems[s] >= 1).length;
  if (covered === SYSTEMS.length) { score += 15; notes.push('✅ All 6 city systems are present.'); }
  else { score += Math.round(covered * 2); notes.push(`ℹ️ ${covered} of ${SYSTEMS.length} systems covered — place buildings for the rest.`); }

  score = Math.max(0, Math.min(100, score));
  return { score, notes };
}

